/* Relais — robustness of the wire parser (ROB-09): no input may crash it, make
 * it write outside the caller's structure, or make it accept a frame whose
 * control is wrong.
 *
 * Method: a guarded destination. The decoded message lives inside a structure
 * flanked by two sentinel patterns; after every call both patterns must be
 * intact, which catches any write past the end of relais_msg. The corpus is
 * generated by the shared PRNG (t_rng), so a failure is reproducible.
 *
 * Requirements covered here:
 *   ROB-09  the parser never trusts its input (200 000 buffers, 0..512 bytes);
 *   SEC-02  a frame whose control is wrong is never accepted;
 *   ROB-02  decoding is deterministic: two passes over the same bytes agree.
 */
#include <string.h>

#include "test_util.h"

#define SENTINEL_WORDS 4u
#define FUZZ_ROUNDS 200000

/* The decoded message, boxed in by sentinels on both sides. */
typedef struct {
  uint32_t before[SENTINEL_WORDS];
  relais_msg msg;
  uint32_t after[SENTINEL_WORDS];
} guarded;

#define SENTINEL_BEFORE 0xA5C3E1F7u
#define SENTINEL_AFTER 0x1B2D4F69u

/* A valid STATUT frame, built from the shared fixture: the fuzz corpus starts
 * from something the encoder really produces, then corrupts it. */
static size_t sample_frame(uint8_t *buf, size_t cap) {
  relais_msg m;
  relais_meas meas;
  memset(&meas, 0, sizeof meas);
  meas.pos = 0.5f;
  t_statut(&m, 4242u, 7u, RELAIS_NODE_B, RELAIS_SRC_HOLDER, 1u, &meas);
  return relais_frame_encode(&m, NULL, buf, cap);
}

static void guard_init(guarded *g) {
  for (size_t i = 0; i < SENTINEL_WORDS; i++) {
    g->before[i] = SENTINEL_BEFORE;
    g->after[i] = SENTINEL_AFTER;
  }
  memset(&g->msg, 0xEE, sizeof g->msg);
}

/* True when both sentinels survived the call. */
static bool guard_intact(const guarded *g) {
  for (size_t i = 0; i < SENTINEL_WORDS; i++) {
    if (g->before[i] != SENTINEL_BEFORE || g->after[i] != SENTINEL_AFTER) return false;
  }
  return true;
}

/* Random buffer of the given length, sometimes dressed up as a plausible frame
 * so that the parser walks past the header and into the payload guards. */
static void fuzz_bytes(t_rng *rng, uint8_t *buf, size_t len, bool plausible) {
  for (size_t i = 0; i < len; i++) buf[i] = (uint8_t)t_rng_below(rng, 256u);
  if (plausible && len >= RELAIS_HEADER_LEN + RELAIS_CHECK_LEN) {
    /* magic, version, type, sender: the four fields the header rule reads. */
    buf[0] = (uint8_t)(RELAIS_MAGIC >> 24);
    buf[1] = (uint8_t)(RELAIS_MAGIC >> 16);
    buf[2] = (uint8_t)(RELAIS_MAGIC >> 8);
    buf[3] = (uint8_t)RELAIS_MAGIC;
    buf[4] = (uint8_t)RELAIS_VERSION;
    buf[5] = (uint8_t)(1u + t_rng_below(rng, 7u)); /* a known type */
    buf[6] = (uint8_t)(1u + t_rng_below(rng, 4u)); /* a known sender */
    /* payload_len consistent with the length actually received, half the time */
    if (t_rng_below(rng, 2u) == 0u) {
      uint16_t payload = (uint16_t)(len - RELAIS_HEADER_LEN - RELAIS_CHECK_LEN);
      buf[20] = (uint8_t)(payload >> 8);
      buf[21] = (uint8_t)payload;
    }
  }
}

/* The 64-bit trailer of a buffer, as the decoder reads it. */
static uint64_t trailer(const uint8_t *buf, size_t len) {
  return relais_frame_read_u64(buf + len - RELAIS_CHECK_LEN);
}

void test_rob09_fuzz_never_writes_outside(void) {
  t_section("ROB-09 200000 random buffers, guarded destination");
  t_rng rng;
  t_rng_seed(&rng, 0x51ED2u);
  static uint8_t buf[RELAIS_FRAME_MAX];
  guarded g;
  long accepted = 0, bad_sentinel = 0, accepted_bad_check = 0, unchecked_true = 0;

  for (long i = 0; i < FUZZ_ROUNDS; i++) {
    size_t len = (size_t)t_rng_below(&rng, RELAIS_FRAME_MAX + 1u);
    fuzz_bytes(&rng, buf, len, (i & 1) == 0);

    guard_init(&g);
    relais_reject why = RELAIS_REJ_NONE;
    bool ok = relais_frame_decode(buf, len, NULL, &g.msg, &why);
    if (!guard_intact(&g)) bad_sentinel++;
    if (ok) {
      accepted++;
      /* SEC-02: nothing is accepted unless its control is right. */
      uint64_t want = relais_check_compute(NULL, buf, len - RELAIS_CHECK_LEN);
      if (want != trailer(buf, len)) accepted_bad_check++;
    }

    guard_init(&g);
    if (relais_frame_decode_unchecked(buf, len, &g.msg)) unchecked_true++;
    if (!guard_intact(&g)) bad_sentinel++;
  }
  T_EQ_U((uint64_t)bad_sentinel, 0u);
  T_EQ_U((uint64_t)accepted_bad_check, 0u);
  /* The corpus is supposed to reach the parser, not only be rejected at the
   * magic: some random buffers do decode unchecked. */
  T_CHECK(unchecked_true > 0);
  T_CHECK(unchecked_true >= accepted);
}

void test_rob09_decode_is_deterministic(void) {
  t_section("ROB-09 two decodes of the same buffer agree");
  t_rng rng;
  t_rng_seed(&rng, 0xD37E2u);
  static uint8_t buf[RELAIS_FRAME_MAX];
  long differ = 0;
  for (long i = 0; i < 2000; i++) {
    size_t len = (size_t)t_rng_below(&rng, RELAIS_FRAME_MAX + 1u);
    fuzz_bytes(&rng, buf, len, true);
    relais_msg a, b, c;
    memset(&a, 0x11, sizeof a);
    memset(&b, 0x22, sizeof b);
    bool ok_a = relais_frame_decode_unchecked(buf, len, &a);
    bool ok_b = relais_frame_decode_unchecked(buf, len, &b);
    if (ok_a != ok_b || (ok_a && memcmp(&a, &b, sizeof a) != 0)) differ++;
    /* The checked parser is deterministic as well, whatever the buffer is. */
    bool ok_c = relais_frame_decode(buf, len, NULL, &c, NULL);
    relais_msg d;
    bool ok_d = relais_frame_decode(buf, len, NULL, &d, NULL);
    if (ok_c != ok_d || (ok_c && memcmp(&c, &d, sizeof c) != 0)) differ++;
  }
  T_EQ_U((uint64_t)differ, 0u);
}

/* ROB-09/SEC-01: a valid frame with one bit flipped anywhere in the body is
 * refused, and the destination stays untouched by anything but the decode. */
void test_rob09_single_bit_flip_anywhere_refused(void) {
  t_section("SEC-02 single bit flipped anywhere: frame never accepted");
  uint8_t good[RELAIS_FRAME_MAX];
  uint8_t buf[RELAIS_FRAME_MAX];
  size_t n = sample_frame(good, sizeof good);
  T_CHECK(n > RELAIS_HEADER_LEN + RELAIS_CHECK_LEN);
  long accepted = 0;
  /* Every byte of the frame body, then every bit of it: 8 * (n - 8) cases. */
  for (size_t pos = 0; pos + RELAIS_CHECK_LEN < n; pos++) {
    for (unsigned bit = 0; bit < 8u; bit++) {
      memcpy(buf, good, n);
      buf[pos] = (uint8_t)(buf[pos] ^ (uint8_t)(1u << bit));
      guarded g;
      guard_init(&g);
      if (relais_frame_decode(buf, n, NULL, &g.msg, NULL)) accepted++;
      if (!guard_intact(&g)) accepted += 1000000; /* sentinel breach counts */
    }
  }
  T_EQ_U((uint64_t)accepted, 0u);
}

int main(void) {
  test_rob09_fuzz_never_writes_outside();
  test_rob09_decode_is_deterministic();
  test_rob09_single_bit_flip_anywhere_refused();
  return t_summary();
}
